"use client";

import React, { useState, useEffect } from "react";
import { motion, useSpring, useTransform } from "motion/react";
import { Plus, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

export interface LoadingProgressBarProps
  extends React.HTMLAttributes<HTMLDivElement> {
  value?: number;
  autoIncrement?: boolean;
}

export function LoadingProgressBar({
  value: propValue,
  autoIncrement = true,
  className,
  ...props
}: LoadingProgressBarProps) {
  const [internalValue, setInternalValue] = useState(15);
  const isControlled = propValue !== undefined;
  const targetValue = isControlled ? propValue : internalValue;

  const springValue = useSpring(targetValue, {
    stiffness: 70,
    damping: 15,
    mass: 0.8,
  });

  const scaleX = useTransform(springValue, (val) => Math.min(1, Math.max(0, val / 100)));

  useEffect(() => {
    if (isControlled || !autoIncrement) return;
    const interval = setInterval(() => {
      setInternalValue((prev) => {
        if (prev >= 100) return 0;
        return Math.min(100, prev + Math.floor(Math.random() * 30 + 10));
      });
    }, 1200);
    return () => clearInterval(interval);
  }, [isControlled, autoIncrement]);

  return (
    <div
      data-slot="loading-progress-bar"
      className={cn(
        "flex flex-col items-center justify-center gap-5 w-full max-w-sm mx-auto p-6 rounded-3xl border border-neutral-200 bg-white/80 dark:border-neutral-800 dark:bg-neutral-900/80 shadow-xl backdrop-blur-md select-none",
        className
      )}
      {...props}
    >
      <div className="flex items-center justify-between w-full text-xs font-mono">
        <span className="text-neutral-500 font-semibold">Downloading Assets</span>
        <span className="font-bold text-pink-500">{Math.round(targetValue)}%</span>
      </div>

      {/* Progress Track */}
      <div className="relative h-3 w-full overflow-hidden rounded-full bg-neutral-100 dark:bg-neutral-800">
        <motion.div
          style={{ scaleX }}
          className="h-full w-full origin-left rounded-full bg-gradient-to-r from-pink-500 to-rose-500 shadow-[0_0_12px_rgba(244,63,94,0.5)] will-change-transform"
        />
      </div>

      {/* Manual Step Controls */}
      <div className="flex items-center gap-3 mt-1">
        <button
          type="button"
          onClick={() => setInternalValue((v) => Math.min(100, v + 25))}
          className="flex items-center gap-1.5 rounded-full border border-neutral-200 bg-neutral-50 px-3.5 py-1.5 text-xs font-semibold text-neutral-700 transition-all hover:bg-neutral-100 dark:border-neutral-800 dark:bg-neutral-800 dark:text-neutral-300 dark:hover:bg-neutral-700 cursor-pointer"
        >
          <Plus className="h-3.5 w-3.5" />
          <span>+25% Jump</span>
        </button>

        <button
          type="button"
          onClick={() => setInternalValue(0)}
          className="flex items-center gap-1.5 rounded-full border border-neutral-200 bg-neutral-50 px-3.5 py-1.5 text-xs font-semibold text-neutral-700 transition-all hover:bg-neutral-100 dark:border-neutral-800 dark:bg-neutral-800 dark:text-neutral-300 dark:hover:bg-neutral-700 cursor-pointer"
        >
          <RotateCcw className="h-3.5 w-3.5" />
          <span>Reset</span>
        </button>
      </div>
    </div>
  );
}
